// vero quando la finestra è larga quanto un cellulare: usato per ingrandire
// le viste calendario (altrimenti le barre dei corsi diventano illeggibili
// su schermi stretti, dato che lo spazio orizzontale per giorno si riduce
// molto ma il testo resterebbe alla stessa dimensione)
function useIsMobile(breakpoint = 700) {
  const [isMobile, setIsMobile] = useState(() => typeof window !== "undefined" && window.innerWidth <= breakpoint);
  useEffect(() => {
    function aggiorna() { setIsMobile(window.innerWidth <= breakpoint); }
    window.addEventListener("resize", aggiorna);
    return () => window.removeEventListener("resize", aggiorna);
  }, [breakpoint]);
  return isMobile;
}

// vero quando lo schermo è in verticale (portrait): usato per decidere se
// una tabella molto larga va spezzata in schede a due colonne (telefono in
// verticale, tutto leggibile) oppure può restare su una riga sola (telefono
// in orizzontale, dove c'è più larghezza)
function useIsPortrait() {
  const [portrait, setPortrait] = useState(() => (typeof window === "undefined" ? true : window.innerHeight >= window.innerWidth));
  useEffect(() => {
    function aggiorna() { setPortrait(window.innerHeight >= window.innerWidth); }
    window.addEventListener("resize", aggiorna);
    window.addEventListener("orientationchange", aggiorna);
    return () => { window.removeEventListener("resize", aggiorna); window.removeEventListener("orientationchange", aggiorna); };
  }, []);
  return portrait;
}

function fmtData(d) {
  const [y, m, day] = d.split("-");
  return `${day}/${m}/${y}`;
}

// Supabase Storage rifiuta le chiavi con lettere accentate o altri
// caratteri non ASCII ("Invalid key") — i nomi dei file caricati
// dall'utente (es. "Hennè.pdf") vanno sempre ripuliti prima di entrare
// in un percorso di upload: accenti tolti (è→e), tutto il resto che non
// è lettera/numero/punto/trattino diventa "-"
function sanitizzaNomeFile(nome) {
  const base = (nome || "file").normalize("NFD").replace(new RegExp("[\\u0300-\\u036f]", "g"), "");
  return base.replace(/[^a-zA-Z0-9.-]+/g, "-");
}

// wa.me vuole solo cifre col prefisso internazionale: i numeri qui sono
// quasi sempre cellulari italiani inseriti senza prefisso, quindi si
// aggiunge "39" solo se non sembra già averlo (numero internazionale più lungo)
function numeroWhatsapp(telefono) {
  const cifre = (telefono || "").replace(/\D/g, "");
  return cifre.length > 10 ? cifre : `39${cifre}`;
}
