// somma delle spese vere già registrate per quella classe+sotto-categoria
const CAMPI_RIEPILOGO_AMMINISTRATIVO = [
  { chiave: "costo_accademia", etichetta: "Costo accademia", categoriaId: "affitto_aule_esterne", sottocategoriaId: "affitto_aule_esterne__quota_accademia" },
  { chiave: "costo_master", etichetta: "Costo master", categoriaId: "docenti_corsi", sottocategoriaId: "docenti_corsi__compensi_master" },
  { chiave: "costo_assistenti", etichetta: "Costo assistenti", categoriaId: "docenti_corsi", sottocategoriaId: "docenti_corsi__compensi_assistenti" },
  { chiave: "costo_pranzi", etichetta: "Costo pranzi", categoriaId: "vitto_corsi", sottocategoriaId: "vitto_corsi__costo_pranzi" },
  { chiave: "rimborso_cene", etichetta: "Rimborso cene", categoriaId: "vitto_corsi", sottocategoriaId: "vitto_corsi__rimborso_cene" },
  { chiave: "rimborso_colazioni_spesa", etichetta: "Rimborso colazioni e spesa", categoriaId: "vitto_corsi", sottocategoriaId: "vitto_corsi__rimborso_colazioni" },
  { chiave: "costo_hotel", etichetta: "Costo appartamento/hotel", categoriaId: "alloggi_corsi", sottocategoriaId: "alloggi_corsi__hotel" },
  { chiave: "costo_coordinatore", etichetta: "Costo coordinatore", categoriaId: "personale_accademia", sottocategoriaId: "personale_accademia__costo_coordinatore" },
  { chiave: "rimborso_taxi", etichetta: "Rimborso taxi", categoriaId: "viaggi_corsi", sottocategoriaId: "viaggi_corsi__taxi_trasporti_locali" },
  { chiave: "rimborso_parcheggi", etichetta: "Rimborso parcheggi", categoriaId: "viaggi_corsi", sottocategoriaId: "viaggi_corsi__rimborso_parcheggi" },
];

const ALIQUOTA_IVA_RIEPILOGO_CLASSE = 22;

// una riga della tabella "Costi della classe" (Riepilogo amministrativo):
// Imponibile/Con IVA e % pagata cash/Importo pagato cash sono coppie di
// campi che si ricalcolano a vicenda — servono stati locali controllati
// (non i soliti defaultValue+onBlur non controllati usati altrove) perché
// il blur di un campo deve aggiornare il valore MOSTRATO in un altro
// riga della tabella "Spese" per una spesa vera (Titolo/Totale/Bonifico/
// Cash): "Totale" è l'unico importo mostrato/modificabile a vista —
// l'imponibile (spese.imponibile) resta calcolato dietro le quinte al
// 22% per non rompere l'Analisi costi aziendale, che lo legge. "Cash" è
// l'unico campo libero (spese.importo_pagato_cash); "Bonifico" è sempre
// il complemento (Totale − Cash), sola lettura — niente più percentuale
function RigaCostoClasse({ spesa, onSalva, onElimina, costiCategorie, costiSottocategorie }) {
  const [totale, setTotale] = useState(spesa.totale != null ? String(spesa.totale) : "");
  const [cash, setCash] = useState(spesa.importo_pagato_cash != null ? String(spesa.importo_pagato_cash) : "");

  useEffect(() => {
    setTotale(spesa.totale != null ? String(spesa.totale) : "");
    setCash(spesa.importo_pagato_cash != null ? String(spesa.importo_pagato_cash) : "");
  }, [spesa.totale, spesa.importo_pagato_cash]);

  const vociTitolo = CAMPI_RIEPILOGO_AMMINISTRATIVO;
  const titoloCorrisponde = vociTitolo.some((c) => c.sottocategoriaId === spesa.sottocategoria_id);
  const totaleNum = totale === "" ? 0 : parseNum(totale);
  const cashNum = cash === "" ? 0 : parseNum(cash);
  const bonifico = round2(totaleNum - cashNum);

  function commitTotale() {
    const v = totale === "" ? null : parseNum(totale);
    if (v === (spesa.totale ?? null)) return;
    const nuovoImponibile = v == null ? null : round2(v / (1 + ALIQUOTA_IVA_RIEPILOGO_CLASSE / 100));
    onSalva({ totale: v, imponibile: nuovoImponibile });
  }
  function commitCash() {
    const v = cash === "" ? null : parseNum(cash);
    if (v === (spesa.importo_pagato_cash ?? null)) return;
    onSalva({ importo_pagato_cash: v });
  }

  return (
    <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 3, flexWrap: "wrap" }}>
      <div style={{ flex: "2 1 170px", minWidth: 0 }}>
        <select
          style={campoCompattoStyle}
          value={titoloCorrisponde ? spesa.sottocategoria_id || "" : "__altro__"}
          onChange={(e) => {
            const scelta = vociTitolo.find((c) => c.sottocategoriaId === e.target.value);
            if (scelta) onSalva({ categoria_id: scelta.categoriaId, sottocategoria_id: scelta.sottocategoriaId });
          }}
        >
          {!titoloCorrisponde && (
            <option value="__altro__">
              {sottocategoriaCostoDi(costiSottocategorie, spesa.sottocategoria_id)?.nome || categoriaCostoDi(costiCategorie, spesa.categoria_id)?.nome || "Altra voce"}
            </option>
          )}
          {vociTitolo.map((c) => <option key={c.chiave} value={c.sottocategoriaId}>{c.etichetta}</option>)}
        </select>
      </div>
      <div style={{ flex: "1 1 90px", minWidth: 0 }}>
        <input style={campoCompattoStyle} inputMode="decimal" value={totale} onChange={(e) => setTotale(e.target.value)} onBlur={commitTotale} />
      </div>
      <div style={{ flex: "1 1 90px", minWidth: 0 }}>
        <div style={{ ...campoCompattoStyle, background: "#EFEFEF", color: MUTED }}>€ {bonifico}</div>
      </div>
      <div style={{ flex: "1 1 90px", minWidth: 0 }}>
        <input style={campoCompattoStyle} inputMode="decimal" value={cash} onChange={(e) => setCash(e.target.value)} onBlur={commitCash} />
      </div>
      <button
        onClick={onElimina}
        title="Elimina voce"
        style={{ width: 26, height: 26, borderRadius: 6, border: `1px solid ${CREAM_BORDER}`, background: "#fff", color: "#C0392B", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
      >
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="3 6 5 6 21 6" />
          <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
          <path d="M10 11v6" /><path d="M14 11v6" />
        </svg>
      </button>
    </div>
  );
}

